public class Order
{
    public Order(long creditLimitCents) => CreditLimitCents = creditLimitCents;
    public long CreditLimitCents { get; }
    public long TotalCents { get; private set; }
    private readonly List<OrderLine> _lines = new();
    public IReadOnlyList<OrderLine> Lines => _lines.AsReadOnly();
    public void AddLine(OrderLine line)
    {
        if (TotalCents + line.AmountCents > CreditLimitCents) throw new LimitExceededException();
        _lines.Add(line); TotalCents += line.AmountCents;
    }
}
